package android.app;import android.content.*;import android.view.*;public class Dialog implements DialogInterface {public final Context context;public final Window window;public View content;public boolean showing,cancelable=true,outside=true;public OnDismissListener dismissListener;public Dialog(Context c){context=c;window=new Window(c);}public Context getContext(){return context;}public Window getWindow(){return window;}public boolean requestWindowFeature(int f){return (Boolean)rv.batch.Platform.invoke("dialog.feature",this,f);}public void setContentView(View v){content=v;rv.batch.Platform.invoke("dialog.content",this,v);}public void setCancelable(boolean b){cancelable=b;}public void setCanceledOnTouchOutside(boolean b){outside=b;}public void setOnDismissListener(OnDismissListener l){dismissListener=l;}public boolean isShowing(){return showing;}public void show(){rv.batch.Platform.invoke("dialog.show",this);showing=true;}public void dismiss(){if(!showing)return;rv.batch.Platform.invoke("dialog.dismiss",this);showing=false;if(dismissListener!=null)dismissListener.onDismiss(this);}}
